"""Append-only activity stream for storefront operations."""

from __future__ import annotations

KIND_SALE = "sale"
KIND_CANCEL = "cancellation"


class ActivityEvent:
    def __init__(self, kind: str, actor_id: int, order_id: int, **extra: object) -> None:
        self.kind = kind
        self.actor_id = actor_id
        self.order_id = order_id
        self.extra = extra

    def as_dict(self) -> dict:
        payload = {
            "kind": self.kind,
            "actor_id": self.actor_id,
            "order_id": self.order_id,
        }
        payload.update(self.extra)
        return payload

    def is_open_sale(self) -> bool:
        return self.kind == KIND_SALE


_EVENTS: list[ActivityEvent] = []


def append_event(kind: str, actor_id: int, order_id: int, **extra: object) -> dict:
    event = ActivityEvent(kind, actor_id, order_id, **extra)
    _EVENTS.append(event)
    return event.as_dict()


def record_sale(actor_id: int, order_id: int, total: float) -> dict:
    return append_event(KIND_SALE, actor_id, order_id, total=float(total))


def record_cancellation(actor_id: int, order_id: int) -> dict:
    return append_event(KIND_CANCEL, actor_id, order_id)


def events_for_order(order_id: int) -> list[dict]:
    return [event.as_dict() for event in _EVENTS if event.order_id == order_id]


def events_for_actor(actor_id: int) -> list[dict]:
    return [event.as_dict() for event in _EVENTS if event.actor_id == actor_id]


def latest_for_order(order_id: int) -> dict | None:
    matches = events_for_order(order_id)
    if not matches:
        return None
    return matches[-1]


def open_sales() -> list[dict]:
    latest: dict[int, ActivityEvent] = {}
    for event in _EVENTS:
        latest[event.order_id] = event
    return [event.as_dict() for event in latest.values() if event.is_open_sale()]


def count() -> int:
    return len(_EVENTS)


def reset_store() -> None:
    _EVENTS.clear()

"""Card capture and refunds.

Charge failures in some code paths are documented as failing closed with HTTP
500. Restoring warehouse stock after a refund is inventory's job, not this
module's ledger.
"""

_CHARGES: list[dict] = []


def charge(user_id: int, amount: float, items: list[dict]) -> dict:
    rec = {
        "user_id": user_id,
        "amount": amount,
        "items": items,
        "status": "captured",
    }
    _CHARGES.append(rec)
    return rec


def refund(order: dict) -> dict:
    """Mark a capture as refunded. Does not touch warehouse stock."""
    return {"refunded": True, "amount": order.get("total", 0)}


def fail_closed_message() -> str:
    """Red herring for searches about crashes / HTTP 500."""
    return "charge failures should fail closed with HTTP 500"


def reset_store() -> None:
    _CHARGES.clear()

"""Staff macros and ticket drafts."""

from __future__ import annotations

from app import notifications


class Ticket:
    def __init__(self, user_id: int, subject: str, body: str) -> None:
        self.user_id = user_id
        self.subject = subject
        self.body = body
        self.status = "open"

    def close(self) -> None:
        self.status = "closed"

    def as_dict(self) -> dict:
        return {
            "user_id": self.user_id,
            "subject": self.subject,
            "body": self.body,
            "status": self.status,
        }


_TICKETS: list[Ticket] = []
_MACROS = {
    "shipping": "We shipped your parcel.",
    "refund": "We received your cancellation request.",
}


def open_ticket(user_id: int, subject: str, body: str) -> dict:
    ticket = Ticket(user_id, subject, body)
    _TICKETS.append(ticket)
    return ticket.as_dict()


def close_ticket(index: int) -> dict:
    ticket = _TICKETS[index]
    ticket.close()
    return ticket.as_dict()


def macro_text(name: str) -> str:
    return _MACROS.get(name, "")


def notify_ticket(user_id: int, subject: str) -> dict:
    return notifications.dispatch_notice(user_id, "support", subject)


def open_tickets() -> list[dict]:
    return [ticket.as_dict() for ticket in _TICKETS if ticket.status == "open"]


def all_tickets() -> list[dict]:
    return [ticket.as_dict() for ticket in _TICKETS]


def reset_store() -> None:
    _TICKETS.clear()

"""FastAPI app wiring."""

from fastapi import FastAPI, Header, HTTPException
from pydantic import BaseModel

from app import (
    auth,
    calculator,
    inventory,
    orders,
    reports,
    users,
    validators,
)


app = FastAPI(title="issue-pilot-benchmark")


class LoginBody(BaseModel):
    email: str
    password: str


class OrderItem(BaseModel):
    sku: str = "widget"
    price: float
    qty: int


class CreateOrderBody(BaseModel):
    items: list[OrderItem]
    coupon: str | None = None


class EmailBody(BaseModel):
    email: str


def _bearer(authorization: str) -> str:
    if not authorization or not authorization.lower().startswith("bearer "):
        raise HTTPException(status_code=401, detail="missing bearer token")
    return authorization.split(" ", 1)[1].strip()


@app.post("/auth/login")
def login(body: LoginBody) -> dict:
    token = users.login(body.email, body.password)
    return {"access_token": token}


@app.get("/auth/me")
def me(authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    user_id = auth.get_current_user_id(token)
    return {"user_id": user_id}


@app.get("/users/{user_id}")
def get_user_endpoint(user_id: int) -> dict:
    user = users.get_user(user_id)
    return {"id": user_id, "email": user["email"], "role": user["role"]}


@app.post("/users/{user_id}/promote")
def promote_endpoint(user_id: int, authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    auth.require_admin(token)
    user = users.promote_user(user_id)
    return {"id": user_id, "role": user["role"]}


@app.post("/orders")
def create_order_endpoint(
    body: CreateOrderBody,
    authorization: str = Header(...),
    idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
) -> dict:
    token = _bearer(authorization)
    user_id = auth.get_current_user_id(token)
    items = [i.model_dump() for i in body.items]
    return orders.create_order(
        user_id=user_id,
        items=items,
        idempotency_key=idempotency_key,
        coupon=body.coupon,
    )


@app.post("/orders/{order_id}/refund")
def refund_endpoint(order_id: int, authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    auth.get_current_user_id(token)
    return orders.refund_order(order_id)


@app.get("/inventory/{sku}")
def stock_endpoint(sku: str) -> dict:
    return {"sku": sku, "stock": inventory.get_stock(sku)}


@app.post("/validate/email")
def validate_email(email: str) -> dict:
    return {"valid": validators.is_valid_email(email)}


@app.get("/calc/sum")
def calc_sum(start: int, end: int) -> dict:
    return {"result": calculator.sum_inclusive(start, end)}


@app.patch("/users/me/email")
def change_email_endpoint(body: EmailBody, authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    user_id = auth.get_current_user_id(token)
    return users.change_email(user_id, body.email)


@app.get("/notifications/inbox")
def inbox_endpoint(authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    user_id = auth.get_current_user_id(token)
    from app import notifications

    return {"messages": notifications.list_messages(user_id)}


@app.get("/audit/events")
def audit_events_endpoint(order_id: int, authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    auth.get_current_user_id(token)
    from app import audit

    return {"events": audit.events_for_order(order_id)}


@app.get("/reports/sales")
def sales_report_endpoint(authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    user_id = auth.get_current_user_id(token)
    if users.get_user(user_id).get("role") != "admin":
        raise HTTPException(status_code=403, detail="admin required")
    return reports.build_snapshot()

